const { chromium } = require('/var/tmp/avb-runs/avb-ZSViYc/project/node_modules/playwright');
const base = 'http://127.0.0.1:' + process.env.PORT;
const pages = ['index.html','products.html','pricing.html','orders.html','about.html','contact.html'];
const widths = [320, 360, 390, 480, 600, 720, 721, 768, 820, 900, 1024, 1100, 1280];
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  for (const w of widths) {
    await page.setViewportSize({ width: w, height: 900 });
    for (const p of pages) {
      await page.goto(base + '/' + p);
      const r = await page.evaluate(() => {
        const de = document.documentElement;
        const over = [];
        document.querySelectorAll('body *').forEach(el => {
          const b = el.getBoundingClientRect();
          if (b.width && b.right > de.clientWidth + 1) over.push(el.className || el.tagName);
        });
        return { sw: de.scrollWidth, cw: de.clientWidth, over: [...new Set(over)].slice(0,5) };
      });
      if (r.sw > r.cw || r.over.length) console.log(w, p, JSON.stringify(r));
    }
  }
  await browser.close();
})();
EOF
