cat > $TMPDIR/csscheck.js <<'EOF'
const { chromium } = require('/var/tmp/avb-runs/avb-ZSViYc/project/node_modules/playwright');
const base = 'http://127.0.0.1:' + process.env.PORT;
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto(base + '/index.html');
  const out = await page.evaluate(() => {
    const res = [];
    for (const sheet of document.styleSheets) {
      const rules = [...sheet.cssRules];
      res.push({href: sheet.href.split('/').pop(), count: rules.length, empty: rules.filter(r => !r.cssText.trim()).length});
      // find declarations that got dropped: count braces per rule text vs style.length
    }
    // For every style rule, compare raw declaration count to parsed style length
    const mismatches = [];
    for (const sheet of document.styleSheets) {
      for (const rule of sheet.cssRules) {
        if (!rule.style) continue;
        const raw = rule.cssText.slice(rule.cssText.indexOf('{')+1, rule.cssText.lastIndexOf('}'));
        const rawCount = raw.split(';').filter(s => s.trim()).length;
        // nested at-rules skipped
        if (rawCount !== rule.style.length) {
          mismatches.push({sel: rule.selectorText, rawCount, parsed: rule.style.length, text: rule.cssText.slice(0,120)});
        }
      }
    }
    return {res, mismatches};
  });
  console.log(JSON.stringify(out, null, 2));
  await browser.close();
})();
EOF
node server.js & SRV=$!; sleep 1.2; node $TMPDIR/csscheck.js; kill $SRV 2>/dev/null

