  await p.goto(base + '/products.html');
  const data = await p.evaluate(() => {
    const r = el => { const b = el.getBoundingClientRect(); return {top: Math.round(b.top), bottom: Math.round(b.bottom), left: Math.round(b.left), right: Math.round(b.right), w: Math.round(b.width), h: Math.round(b.height)}; };
    return [...document.querySelectorAll('.card.product')].map(c => ({
      title: c.querySelector('h3').textContent,
      card: r(c),
      body: r(c.querySelector('.card-body')),
      foot: r(c.querySelector('.card-foot')),
      btn: r(c.querySelector('.btn')),
      alignSelf: getComputedStyle(c).alignSelf,
      gridAlign: getComputedStyle(c.parentElement).alignItems,
    }));
  });
  console.log(JSON.stringify(data, null, 2));
  await p.goto(base + '/about.html');
  const t = await p.evaluate(() => {
    const r = el => { const b = el.getBoundingClientRect(); return {left: +b.left.toFixed(1), center: +((b.left+b.right)/2).toFixed(1), w:+b.width.toFixed(1)}; };
    const tl = document.querySelector('.timeline');
    const dots = [...document.querySelectorAll('.timeline-item')].map(i => getComputedStyle(i, '::before').left);
    const first = document.querySelector('.timeline-item');
    return {timeline: r(tl), items: [...document.querySelectorAll('.timeline-item')].map(r), dots};
  });
  console.log(JSON.stringify(t, null, 2));
  await b.close();
})();
EOF
