cat > $TMPDIR/cmp.js <<'EOF'
const { chromium } = require('/var/tmp/avb-runs/avb-ZSViYc/project/node_modules/playwright');
const base = 'http://127.0.0.1:' + process.env.PORT;
const pages = ['index.html','products.html','pricing.html','orders.html','about.html','contact.html'];
const selectors = ['.site-header','.header-inner','.brand','.brand-mark','.brand-name','.site-nav','.nav-link','.site-footer','.footer-inner','h1','.lede','.container','.section-title','main'];
const props = ['fontFamily','fontSize','fontWeight','lineHeight','letterSpacing','color','backgroundColor','padding','margin','display','maxWidth','height','borderBottom','position','gap'];
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1280, height: 900 } });
  const all = {};
  for (const pg of pages) {
    await p.goto(base + '/' + pg);
    all[pg] = await p.evaluate(({selectors, props}) => {
      const out = {};
      for (const s of selectors) {
        const el = document.querySelector(s);
        if (!el) { out[s] = null; continue; }
        const cs = getComputedStyle(el);
        const o = {};
        for (const pr of props) o[pr] = cs[pr];
        const r = el.getBoundingClientRect();
