      const el = document.createElement('div');
      const bad = [];
      // strip comments
      css = css.replace(/\/\*[\s\S]*?\*\//g, '');
      // walk blocks, ignoring at-rule preludes
      let i = 0, depth = 0, sel = '';
      // simplistic: iterate char by char, collect declarations at depth>=1
      let buf = '', selectors = [];
      const stack = [];
      const re = /([^{}]+)\{([^{}]*)\}/g;
      let m;
      while ((m = re.exec(css))) {
        const prelude = m[1].trim().split('\n').pop().trim();
        const body = m[2];
        if (prelude.startsWith('@')) continue;
        for (const part of body.split(';')) {
          const d = part.trim();
          if (!d) continue;
          const idx = d.indexOf(':');
