  for (const pg of pages) {
    await p.goto(base + '/' + pg);
    const out = await p.evaluate(() => {
      function lum(c){const [r,g,b]=c.map(v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)});return 0.2126*r+0.7152*g+0.0722*b}
      function parse(s){const m=s.match(/rgba?\(([^)]+)\)/);if(!m)return null;const a=m[1].split(',').map(x=>parseFloat(x));return {rgb:a.slice(0,3),a:a.length>3?a[3]:1}}
      function bg(el){while(el){const c=parse(getComputedStyle(el).backgroundColor);if(c&&c.a>0.5||c&&c.a>0)return c.rgb;el=el.parentElement}return [255,255,255]}
      const issues=[];
      document.querySelectorAll('body *').forEach(el=>{
        const t=[...el.childNodes].filter(n=>n.nodeType===3&&n.textContent.trim()).map(n=>n.textContent.trim()).join(' ');
        if(!t) return;
        const cs=getComputedStyle(el);
        const fg=parse(cs.color); if(!fg) return;
        const back=bg(el);
        const L1=lum(fg.rgb), L2=lum(back);
        const ratio=(Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05);
        const size=parseFloat(cs.fontSize); const bold=parseInt(cs.fontWeight)>=700;
        const large=size>=24||(size>=18.66&&bold);
        const need=large?3:4.5;
        if(ratio<need) issues.push({text:t.slice(0,40), ratio:+ratio.toFixed(2), color:cs.color, bg:'rgb('+back.join(',')+')', size, weight:cs.fontWeight});
        if(el.scrollWidth>el.clientWidth+1 && cs.overflowX==='hidden') issues.push({text:t.slice(0,40), clipping:true});
      });
      return issues;
    });
    console.log(pg, JSON.stringify(out));
  }
  await b.close();
})();
