const { chromium } = require('/var/tmp/avb-runs/avb-ZSViYc/project/node_modules/playwright');
const base = 'http://127.0.0.1:' + process.env.PORT;
const pages = ['index.html','products.html','pricing.html','orders.html','about.html','contact.html'];
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1280, height: 900 } });
  for (const pg of pages) {
    await p.goto(base + '/' + pg);
    const out = await p.evaluate(() => {
      const rules = [];
      const walk = (rs) => { for (const r of rs) { if (r.cssRules) walk(r.cssRules); else if (r.selectorText && r.style) rules.push({sel: r.selectorText, style: r.style}); } };
      for (const sh of document.styleSheets) walk(sh.cssRules);
      const report = [];
      document.querySelectorAll('body *').forEach(el => {
        if (el.tagName === 'SCRIPT' || el.tagName === 'STYLE') return;
        const byProp = {};
        for (const r of rules) {
          let match = false;
          try { match = el.matches(r.sel); } catch(e) { continue; }
          if (!match) continue;
          for (let i = 0; i < r.style.length; i++) {
            const prop = r.style[i];
            const val = r.style.getPropertyValue(prop);
            (byProp[prop] = byProp[prop] || []).push({sel: r.sel, val});
          }
        }
        for (const [prop, list] of Object.entries(byProp)) {
          const vals = [...new Set(list.map(x => x.val))];
          if (vals.length > 1) {
            // find elements with a class for readability
            const cls = el.className && typeof el.className === 'string' ? '.' + el.className.trim().split(/\s+/).join('.') : el.tagName;
            report.push({el: cls, prop, chain: list.map(x => `${x.sel}=${x.val}`)});
          }
        }
      });
      return report;
    });
