      const walk = (rs) => { for (const r of rs) { if (r.cssRules && r.media) { walk(r.cssRules); } else if (r.selectorText) out.push({sel: r.selectorText, media: r.parentRule ? r.parentRule.conditionText : null}); } };
      for (const sh of [...document.styleSheets]) walk([...sh.cssRules]);
      return out;
    });
    for (const {sel, media} of sels) {
      let n = 0;
      try { n = await p.evaluate(s => document.querySelectorAll(s).length, sel); } catch(e) { n = -1; }
      counts[sel] = (counts[sel] || 0) + n;
      if (media) mediaCounts[sel] = {media, n: (mediaCounts[sel]?.n || 0) + n};
    }
  }
  console.log('zero-match selectors:', JSON.stringify(Object.keys(counts).filter(s => counts[s] === 0), null, 1));
  console.log('selector count:', Object.keys(counts).length);
  await b.close();
})();
EOF
