cat > $TMPDIR/verify.js <<'EOF'
const { chromium } = require('/var/tmp/avb-runs/avb-ZSViYc/project/node_modules/playwright');
const base = 'http://127.0.0.1:' + process.env.PORT;
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1280, height: 900 } });
  await p.goto(base + '/products.html');
  const rows = await p.$$eval('.cards .card', cards => cards.map(c => {
    const r = c.getBoundingClientRect();
    const btn = c.querySelector('.btn').getBoundingClientRect();
    const foot = c.querySelector('.card-foot').getBoundingClientRect();
    return { t: c.querySelector('h3').textContent.trim().slice(0,12), top: Math.round(r.top), h: Math.round(r.height), foot: Math.round(foot.top), btn: Math.round(btn.top) };
  }));
  console.log('products cards:'); rows.forEach(r => console.log(JSON.stringify(r)));
  const bundles = await p.$$eval('.bundles .card', cards => cards.map(c => {
    const r = c.getBoundingClientRect(); const f = c.querySelector('.card-foot').getBoundingClientRect();
    return { t: c.querySelector('h3').textContent.trim(), top: Math.round(r.top), h: Math.round(r.height), footFromBottom: Math.round(r.bottom - f.bottom) };
  }));
  console.log('bundles:'); bundles.forEach(r => console.log(JSON.stringify(r)));
  // layouts on other pages: no clipping/overflow from body flex
  for (const path of ['/', '/about.html', '/contact.html', '/pricing.html', '/orders.html']) {
    await p.goto(base + path);
    const bad = await p.evaluate(() => {
      const out = [];
      document.querySelectorAll('.card-body').forEach(el => {
        const c = el.closest('.card');
        if (el.scrollHeight > el.clientHeight + 1) out.push('body overflow ' + c.className + ' ' + (el.scrollHeight - el.clientHeight));
        const cs = getComputedStyle(c);
        if (cs.display !== 'grid' && cs.display !== 'flex') out.push('unexpected display ' + c.className + ' ' + cs.display);
      });
      return out;
    });
    console.log(path, bad.length ? bad : 'ok');
  }
  await p.goto(base + '/products.html'); await p.screenshot({ path: process.env.TMPDIR + '/after-products-1280.png', fullPage: true });
  await p.setViewportSize({ width: 390, height: 844 }); await p.goto(base + '/products.html'); await p.screenshot({ path: process.env.TMPDIR + '/after-products-390.png', fullPage: true });
  await b.close();
})();
EOF
node server.js & SRV=$!; sleep 1.5; node $TMPDIR/verify.js; kill $SRV 2>/dev/null

