cat > $TMPDIR/after-all.js <<'EOF'
const { chromium } = require('/var/tmp/avb-runs/avb-ZSViYc/project/node_modules/playwright');
const base = 'http://127.0.0.1:' + process.env.PORT;
const pages = { index: '/', products: '/products.html', pricing: '/pricing.html', orders: '/orders.html', about: '/about.html', contact: '/contact.html' };
(async () => {
  const b = await chromium.launch();
  for (const [name, path] of Object.entries(pages)) {
    const p = await b.newPage({ viewport: { width: 1280, height: 900 } });
    await p.goto(base + path);
    await p.screenshot({ path: process.env.TMPDIR + '/again-desk-' + name + '.png', fullPage: true });
    await p.setViewportSize({ width: 390, height: 844 });
    await p.goto(base + path);
    await p.screenshot({ path: process.env.TMPDIR + '/again-mob-' + name + '.png', fullPage: true });
    await p.close();
  }
  await b.close();
})();
EOF
node server.js & SRV=$!; sleep 1.5; node $TMPDIR/after-all.js; kill $SRV 2>/dev/null
for f in index products pricing orders about contact; do
  a=$(compare -metric AE $TMPDIR/desk-$f.png $TMPDIR/again-desk-$f.png null: 2>&1)
  m=$(compare -metric AE $TMPDIR/mob-$f.png $TMPDIR/again-mob-$f.png null: 2>&1)
  printf '%-9s desktop diff=%-8s mobile diff=%s\n' "$f" "$a" "$m"
done

